flow.set('sysconn_rpc_response_topic', msg.rpcResponseTopic);

let operation = msg.operation || 'read';
const params = msg.rpcParams || {};

// Check if any writable field is present
if (params.gridVoltageLevelCode !== undefined ||
    params.gridStandardRaw !== undefined ||
    params.ratedCapacityAh !== undefined ||
    params.batteryControlModeRaw !== undefined ||
    params.generatorInputModeRaw !== undefined ||
    params.exportLimitModeRaw !== undefined ||
    params.gridFrequencyRaw !== undefined ||
    params.gridTypeRaw !== undefined ||
    params.connectedToGridInputRaw !== undefined ||
    params.lithiumBatteryTypeRaw !== undefined) {
    operation = 'write';
}

msg.operation = operation;

if (operation === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

// Clear all parts
flow.set('sysconn_part_0_2', null);
flow.set('sysconn_part_sn', null);
flow.set('sysconn_part_8_14', null);
flow.set('sysconn_part_15_19', null);
flow.set('sysconn_part_51', null);
flow.set('sysconn_part_204', null);
