    quantity: 1
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data)) {
    node.error('Invalid response for ' + msg.readGroup);
    return null;
}

const group = msg.readGroup;

switch(group) {
    case 'reg0_2':
        flow.set('sysconn_part_0_2', data);
        break;
    case 'sn':
        flow.set('sysconn_part_sn', data);
        break;
    case 'reg8_14':
        flow.set('sysconn_part_8_14', data);
        break;
    case 'reg15_19':
        flow.set('sysconn_part_15_19', data);
        break;
    case 'reg51':
        flow.set('sysconn_part_51', data[0]);
        break;
    case 'reg204':
        flow.set('sysconn_part_204', data[0]);
        break;
    case 'reg213':
        flow.set('sysconn_part_213', data[0]);
        break;
    case 'reg235':
        flow.set('sysconn_part_235', data[0]);
        break;
    case 'reg244':
        flow.set('sysconn_part_244', data[0]);
        break;
    case 'reg285_286':
        flow.set('sysconn_part_285_286', data);
        break;
    case 'reg291':
        flow.set('sysconn_part_291', data[0]);
        break;
    case 'reg325':
        flow.set('sysconn_part_325', data[0]);
        break;
}

// Check if all parts received
const p0_2 = flow.get('sysconn_part_0_2');
const pSn = flow.get('sysconn_part_sn');
const p8_14 = flow.get('sysconn_part_8_14');
const p15_19 = flow.get('sysconn_part_15_19');
const p51 = flow.get('sysconn_part_51');
const p204 = flow.get('sysconn_part_204');
const p213 = flow.get('sysconn_part_213');
const p235 = flow.get('sysconn_part_235');
const p244 = flow.get('sysconn_part_244');
const p285_286 = flow.get('sysconn_part_285_286');
const p291 = flow.get('sysconn_part_291');
const p325 = flow.get('sysconn_part_325');

if (!p0_2 || !pSn || !p8_14 || !p15_19 ||
    p51 === null || p51 === undefined ||
    p204 === null || p204 === undefined ||
    p213 === null || p213 === undefined ||
    p235 === null || p235 === undefined ||
    p244 === null || p244 === undefined ||
    !p285_286 ||
    p291 === null || p291 === undefined ||
    p325 === null || p325 === undefined) {
    return null;
}

// All parts received, pass to build JSON
msg.reg0_2 = p0_2;
msg.snData = pSn;
msg.reg8_14 = p8_14;
msg.reg15_19 = p15_19;
msg.reg51 = p51;
msg.reg204 = p204;
msg.reg213 = p213;
msg.reg235 = p235;
msg.reg244 = p244;
msg.reg285_286 = p285_286;
msg.reg291 = p291;
msg.reg325 = p325;

return msg;

// Extract data
const reg0_2 = msg.reg0_2;
const snData = msg.snData;
const reg8_14 = msg.reg8_14;
const reg15_19 = msg.reg15_19;
const reg51 = msg.reg51;
const reg204 = msg.reg204;
const reg213 = msg.reg213;
const reg235 = msg.reg235;
const reg244 = msg.reg244;
const reg285_286 = msg.reg285_286;
const reg291 = msg.reg291;
const reg325 = msg.reg325;

// Clear flow context
flow.set('sysconn_part_0_2', null);
flow.set('sysconn_part_sn', null);
flow.set('sysconn_part_8_14', null);
flow.set('sysconn_part_15_19', null);
