// === HELPER FUNCTIONS ===
function parseAscii(val, high) {
    const byte = high ? ((val >> 8) & 0xFF) : (val & 0xFF);
    if (byte >= 0x20 && byte <= 0x7E) {
        return String.fromCharCode(byte);
    }
    return '';
}

function parseSerialNumber(regs) {
    let sn = '';
    for (let i = 0; i < 5; i++) {
        sn += parseAscii(regs[i], true);
        sn += parseAscii(regs[i], false);
    }
    return sn.trim();
}

// === MAPPING FUNCTIONS ===
function getDeviceType(code) {
    const types = {
        0x0002: 'String Inverter',
        0x0003: 'Single-phase Storage Inverter',
        0x0008: 'Single-phase Storage Inverter',
        0x0200: 'String Inverter',
        0x0300: 'Single-phase Storage Inverter',
        0x0400: 'Microinverter',
        0x0500: 'Three-phase Storage Inverter'
    };
    return types[code] || 'Unknown (0x' + code.toString(16) + ')';
}

function getBatteryControlMode(code) {
    const modes = { 0: 'voltage', 1: 'capacity', 2: 'no_battery' };
    return modes[code] !== undefined ? modes[code] : 'unknown';
}

function getGeneratorInputMode(code) {
    const modes = { 0: 'generator_input_only', 1: 'smart_load_output', 2: 'inverter_input' };
    return modes[code] !== undefined ? modes[code] : 'unknown';
}

function getExportLimitMode(code) {
    const modes = { 0x00: 'sell_enabled', 0x01: 'built_in_meter', 0x02: 'external_meter' };
    return modes[code] !== undefined ? modes[code] : 'unknown';
}

function getGridType(code) {
    const types = {
        0: 'single_phase_240V',
        1: 'split_phase_120_240V',
        2: 'three_phase_208V',
        3: 'single_phase_120V'
    };
    return types[code] !== undefined ? types[code] : 'unknown';
}

function getSafetyType(code) {
    if (code < 3) return '48V_battery';
    if (code === 3) return '24V_battery';
    return 'unknown (' + code + ')';
}

function getGridStandard(code) {
    const standards = {
        0: 'Default', 1: 'INMETRO', 2: 'EN50549', 3: 'EN50438',
        4: 'IEC61727', 5: 'CUSTOM', 6: 'VDE_AR_N_4105',
        7: 'UTE_C15_712_1', 8: 'RD_1699', 9: 'CEI_0_21',
        10: 'G98_G99', 11: 'AS4777'
    };
    return standards[code] !== undefined ? standards[code] : 'Unknown (' + code + ')';
}

function getLithiumBatteryType(code) {
    const types = {
        0x0000: 'PYLON_SOLAX_CAN', 0x0001: 'Tianbonda_RS485',
        0x0002: 'KOK', 0x0003: 'Keith', 0x0004: 'Topai',
        0x0005: 'Pylon_RS485', 0x0006: 'JLSK_RS485',
        0x0007: 'Xinwangda_RS485', 0x0008: 'Xinruineng_RS485',
        0x0009: 'Tianbang_RS485', 0x000A: 'Shenggao_CAN'
    };
    return types[code] !== undefined ? types[code] : 'Unknown (0x' + code.toString(16) + ')';
}

function getGridVoltageLevelCode(code) {
    const levels = { 0: '127V/220V', 1: '220V/380V', 2: 'Level_2', 3: 'Level_3' };
    return levels[code] !== undefined ? levels[code] : 'unknown';
}

// === PARSE VALUES ===
const reg0 = reg0_2[0];   // Device type
const reg1 = reg0_2[1];   // Modbus address
const reg2 = reg0_2[2];   // Protocol version

const reg8 = reg8_14[0];  // Rated power class
const reg9 = reg8_14[1];  // Chip type
const reg10 = reg8_14[2]; // MCU board FW
const reg11 = reg8_14[3]; // Control aux FW
const reg12 = reg8_14[4]; // Control aux FW 2
const reg13 = reg8_14[5]; // Control board FW
const reg14 = reg8_14[6]; // Comm board FW

const reg15 = reg15_19[0]; // Safety type
const reg16 = reg15_19[1]; // Rated power low
const reg17 = reg15_19[2]; // Rated power high
const reg18 = reg15_19[3]; // MPPT & phases
const reg19 = reg15_19[4]; // Grid voltage level

const reg285 = reg285_286[0]; // Grid frequency
const reg286 = reg285_286[1]; // Grid type

const serialNumber = parseSerialNumber(snData);
const ratedPowerW = ((reg17 << 16) | reg16) * 0.1;

// FIXED: Use byte method for MPPT & Phase parsing
// reg18 = 0x0301 means MPPT=3, Phase=1
const mpptCount = (reg18 >> 8) & 0xFF;
const phaseCount = reg18 & 0xFF;

const protoMajor = (reg2 >> 8) & 0xFF;
const protoMinor = reg2 & 0xFF;
const protocolVersion = protoMajor + '.' + protoMinor;
const gridFreqHz = reg285 === 0 ? 50 : 60;

// Build MPPT array
const mpptArray = [];
for (let i = 1; i <= 4; i++) {
    mpptArray.push({
        pvChannelId: i,
        supportsInput: i <= mpptCount,
        stringMaxCurrentA: null,
        stringMaxVoltageV: null,
        recommendedVocAtStcV: null
    });
}

const deviceId = global.get('DEVICE_ID') || env.get('DEVICE_ID') || 'INVERTER-001';

// === BUILD STATE ===
const state = {
    kind: 'SystemConnectionStructure',
    timestampUtc: new Date().toISOString(),
    version: '1.0',
    schemaVersion: 1,
    deviceId: deviceId,

    inverter: {
        deviceType: getDeviceType(reg0),
        deviceTypeRaw: reg0,
        inverterModel: null,
        serialNumber: serialNumber,

        firmware: {
            protocolVersion: protocolVersion,
            protocolVersionRaw: reg2,
            mcuBoardRaw: reg10,
            controlMainRaw: reg13,
            commMainRaw: reg14
        },

        ratedPowerW: Math.round(ratedPowerW),

        acSide: {
            mpptAndPhasesRaw: reg18,
            batteryInputCount: null,
            outputTopology: null,
            gridType: getGridType(reg286),
            gridTypeRaw: reg286,
            regionVariant: null,
            safetyType: getSafetyType(reg15),
            safetyTypeRaw: reg15,
            gridPhaseCount: phaseCount,
            gridStandard: getGridStandard(reg51),
            gridStandardRaw: reg51,
            gridFrequencyHz: gridFreqHz,
            gridFrequencyRaw: reg285,
            gridVoltageLevelCode: reg19,
            gridVoltageLevel: getGridVoltageLevelCode(reg19),
            gridPhaseSequence: null,
            itSystemNeutralUngrounded: null
        }
    },

    battery: {
        batteryControlMode: getBatteryControlMode(reg213),
        batteryControlModeRaw: reg213,

        batteryChannels: [
            {
                channelId: 1,
                ratedCapacityAh: reg204,
                nominalVoltageV: null,
                batterySn: null,
                batteryPhysicalAddress: null,
                batterySoftwareVersion: null,
                lithiumBatteryType: getLithiumBatteryType(reg325),
                lithiumBatteryTypeRaw: reg325
            }
        ]
    },

    generator: {
        inputMode: getGeneratorInputMode(reg235),
        inputModeRaw: reg235,
        connectedToGridInput: reg291 === 1,
        connectedToGridInputRaw: reg291
    },

    pv: {
        mpptCount: mpptCount,
        mppt: mpptArray
    },

    loadAndGrid: {
        homeLoadConnectionPoint: null,
        exportLimitMode: getExportLimitMode(reg244),
        exportLimitModeRaw: reg244,
        currentTransformerOnGridSide: null,
        supportsBackupLoad: null,
        supportsZeroExport: null,
        supportsExternalMeter: null
    },

    _raw: {
        reg0: reg0, reg1: reg1, reg2: reg2,
        reg8: reg8, reg9: reg9, reg10: reg10,
        reg11: reg11, reg12: reg12, reg13: reg13, reg14: reg14,
        reg15: reg15, reg16: reg16, reg17: reg17, reg18: reg18, reg19: reg19,
        reg51: reg51, reg204: reg204, reg213: reg213, reg235: reg235,
        reg244: reg244, reg285: reg285, reg286: reg286, reg291: reg291, reg325: reg325
    }
};

// Check if this is after a write
const writeResult = flow.get('sysconn_write_result');
flow.set('sysconn_write_result', null);

const rpcResponseTopic = flow.get('sysconn_rpc_response_topic');
flow.set('sysconn_rpc_response_topic', null);

if (writeResult) {
    msg.payload = {
        success: true,
        message: 'Successfully wrote ' + writeResult.count + ' register(s)',
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const params = msg.rpcParams || {};
const writes = [];

// 019: gridVoltageLevelCode [0-3]
if (params.gridVoltageLevelCode !== undefined) {
    const val = Math.max(0, Math.min(3, params.gridVoltageLevelCode));
    writes.push({ register: 19, value: val, name: 'Grid Voltage Level' });
}

// 051: gridStandardRaw [0-20]
if (params.gridStandardRaw !== undefined) {
    const val = Math.max(0, Math.min(20, params.gridStandardRaw));
    writes.push({ register: 51, value: val, name: 'Grid Standard' });
}

// 204: ratedCapacityAh [0-2000]
if (params.ratedCapacityAh !== undefined) {
    const val = Math.max(0, Math.min(2000, params.ratedCapacityAh));
    writes.push({ register: 204, value: val, name: 'Battery Capacity' });
}

// 213: batteryControlModeRaw [0-2]
if (params.batteryControlModeRaw !== undefined) {
    const val = Math.max(0, Math.min(2, params.batteryControlModeRaw));
    writes.push({ register: 213, value: val, name: 'Battery Control Mode' });
}

// 235: generatorInputModeRaw [0-2]
if (params.generatorInputModeRaw !== undefined) {
    const val = Math.max(0, Math.min(2, params.generatorInputModeRaw));
    writes.push({ register: 235, value: val, name: 'Generator Input Mode' });
}

// 244: exportLimitModeRaw [0-2]
if (params.exportLimitModeRaw !== undefined) {
    const val = Math.max(0, Math.min(2, params.exportLimitModeRaw));
    writes.push({ register: 244, value: val, name: 'Export Limit Mode' });
}

// 285: gridFrequencyRaw [0-1]
if (params.gridFrequencyRaw !== undefined) {
    const val = params.gridFrequencyRaw === 1 ? 1 : 0;
    writes.push({ register: 285, value: val, name: 'Grid Frequency' });
}

// 286: gridTypeRaw [0-3]
if (params.gridTypeRaw !== undefined) {
    const val = Math.max(0, Math.min(3, params.gridTypeRaw));
    writes.push({ register: 286, value: val, name: 'Grid Type' });
}

// 291: connectedToGridInputRaw [0-1]
if (params.connectedToGridInputRaw !== undefined) {
    const val = params.connectedToGridInputRaw ? 1 : 0;
    writes.push({ register: 291, value: val, name: 'Gen Connected to Grid' });
}

// 325: lithiumBatteryTypeRaw [0-10]
if (params.lithiumBatteryTypeRaw !== undefined) {
    const val = Math.max(0, Math.min(0x000A, params.lithiumBatteryTypeRaw));
    writes.push({ register: 325, value: val, name: 'Lithium Battery Type' });
}

if (writes.length === 0) {
    node.warn('No valid parameters to write');
    return null;
}

global.set('sysconn_write_queue', writes);
global.set('sysconn_write_index', 0);
global.set('sysconn_write_results', []);

node.status({ fill: 'blue', shape: 'dot', text: writes.length + ' writes queued' });

return msg;

const writes = global.get('sysconn_write_queue') || [];
const index = global.get('sysconn_write_index') || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

msg.payload = {
    fc: 6,
    unitid: 1,
    address: current.register,
    value: current.value
};
msg.currentWrite = current;

node.status({ fill: 'blue', shape: 'dot', text: '[' + (index+1) + '/' + writes.length + '] ' + current.name });

return msg;

const writes = global.get('sysconn_write_queue') || [];
let index = global.get('sysconn_write_index') || 0;
const results = global.get('sysconn_write_results') || [];

const current = msg.currentWrite;
if (current) {
    results.push({
        register: current.register,
        name: current.name,
        value: current.value,
        success: true
    });
    global.set('sysconn_write_results', results);
}

index++;
global.set('sysconn_write_index', index);

node.status({ fill: 'green', shape: 'dot', text: current.name + ' OK' });

if (index < writes.length) {
    return [msg, null];
}

// All writes done
flow.set('sysconn_write_result', {
    count: results.length,
    writes: results
});

global.set('sysconn_write_queue', null);
global.set('sysconn_write_index', null);
global.set('sysconn_write_results', null);

return [null, msg];
